import os
import glob
import re
import pytesseract
from PIL import Image, ImageOps
import openpyxl
from datetime import datetime

# Configuration
INPUT_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Sorted by priority from most to least specific
TOTAL_KEYWORDS = [
    'GRAND TOTAL',
    'TOTAL RM',
    'TOTAL: RM',
    'TOTAL AMOUNT',
    'TOTAL',
    'AMOUNT',
    'TOTAL DUE',
    'AMOUNT DUE',
    'BALANCE DUE',
    'NETT TOTAL',
    'NET TOTAL'
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED'
]

def get_ocr_text(img_path, preprocess_func=None):
    img = Image.open(img_path)
    if preprocess_func:
        img = preprocess_func(img)
    return pytesseract.image_to_string(img)

def preprocess_2x(img):
    # Convert to grayscale
    img = img.convert('L')
    # Autocontrast
    img = ImageOps.autocontrast(img)
    # Upscale 2x
    new_size = tuple(2 * x for x in img.size)
    img = img.resize(new_size, Image.LANCZOS)
    return img

def parse_date(text):
    # Common formats mapping to strptime format
    patterns = [
        (r'(\d{4})-(\d{2})-(\d{2})', '%Y-%m-%d'),
        (r'(\d{2})/(\d{2})/(\d{4})', '%d/%m/%Y'),
        (r'(\d{2})-(\d{2})-(\d{4})', '%d-%m-%Y'),
        (r'(\d{2})\.(\d{2})\.(\d{4})', '%d.%m.%Y'),
        (r'(\d{2})\s+([A-Za-z]{3})\s+(\d{4})', '%d %b %Y'), 
        (r'(\d{2})\s+([A-Za-z]+)\s+(\d{4})', '%d %B %Y'), 
    ]

    lines = text.split('\n')
    candidates = []

    for line in lines:
        line = line.strip()
        if not line:
            continue

        for pat, fmt in patterns:
            matches = re.findall(pat, line)
            for match in matches:
                try:
                    dt_str = ""
                    if isinstance(match, tuple):
                        if fmt == '%Y-%m-%d':
                            dt_str = f"{match[0]}-{match[1]}-{match[2]}"
                        elif fmt == '%d/%m/%Y':
                            dt_str = f"{match[0]}/{match[1]}/{match[2]}"
                        elif fmt == '%d-%m-%Y':
                            dt_str = f"{match[0]}-{match[1]}-{match[2]}"
                        elif fmt == '%d.%m.%Y':
                            dt_str = f"{match[0]}.{match[1]}.{match[2]}"
                        elif fmt == '%d %b %Y' or fmt == '%d %B %Y':
                            day, month, year = match
                            month = month.title()
                            dt_str = f"{day} {month} {year}"
                    else:
                        dt_str = match

                    dt = datetime.strptime(dt_str, fmt)
                    if 1900 < dt.year < 2100:
                        candidates.append(dt)
                except ValueError:
                    continue

    if not candidates:
        return None

    return candidates[0].strftime('%Y-%m-%d')

def extract_amount(text):
    lines = text.split('\n')
    cleaned_lines = [l.strip() for l in lines if l.strip()]

    candidates = []

    for i, line in enumerate(cleaned_lines):
        line_upper = line.upper()

        exclude = False
        for ek in EXCLUSION_KEYWORDS:
            if ek in line_upper:
                exclude = True
                break
        if exclude:
            continue

        for priority, kw in enumerate(TOTAL_KEYWORDS):
            if kw in line_upper:
                def find_nums(s):
                     return re.findall(r'(\d+(?:,\d+)*\.\d{2})', s)

                nums = find_nums(line)
                val = None
                if nums:
                    val = nums[-1]
                else:
                    if i + 1 < len(cleaned_lines):
                        next_line = cleaned_lines[i+1]
                        nums_next = find_nums(next_line)
                        if nums_next:
                            val = nums_next[-1]

                if val:
                    try:
                        val_clean = val.replace(',', '')
                        f_val = float(val_clean)
                        candidates.append((priority, f_val))
                    except ValueError:
                        pass

    if not candidates:
        return None

    candidates.sort(key=lambda x: x[0])
    return "{:.2f}".format(candidates[0][1])

def main():
    if not os.path.exists(INPUT_DIR):
        print(f"Error: {INPUT_DIR} does not exist.")
        return

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    image_files = sorted(glob.glob(os.path.join(INPUT_DIR, '*.jpg')))

    if not image_files:
        print("No image files found.")

    for img_path in image_files:
        filename = os.path.basename(img_path)
        print(f"Processing {filename}...")

        try:
            # Pass 1: Raw Image
            text_raw = get_ocr_text(img_path)
            date_str = parse_date(text_raw)
            amount_str = extract_amount(text_raw)

            # Pass 2: Preprocessed Image (if something is missing)
            if date_str is None or amount_str is None:
                print(f"  Refining {filename} with preprocessing...")
                text_2x = get_ocr_text(img_path, preprocess_2x)

                if date_str is None:
                    date_str = parse_date(text_2x)
                if amount_str is None:
                    amount_str = extract_amount(text_2x)

            ws.append([filename, date_str, amount_str])

        except Exception as e:
            print(f"Failed to process {filename}: {e}")
            ws.append([filename, None, None])

    wb.save(OUTPUT_FILE)
    print(f"Saved to {OUTPUT_FILE}")

if __name__ == '__main__':
    main()

